('q_dej-4-karel-iv-praha_1','Kdy byla založena Univerzita Karlova?',ARRAY['v roce 1348','v roce 1212','v roce 1620','v roce 1526']::TEXT[],0,'1348.',1,ARRAY[]::TEXT[],NULL,1,'c_dej-4-karel-iv-praha',NULL,NOW()),
('q_dej-4-karel-iv-praha_2','Který hrad nechal postavit Karel IV. pro uložení korunovačních klenotů?',ARRAY['Karlštejn','Bezděz','Kost','Křivoklát']::TEXT[],0,'Karlštejn.',1,ARRAY[]::TEXT[],NULL,2,'c_dej-4-karel-iv-praha',NULL,NOW()),
('q_dej-4-karel-iv-praha_3','Který most nechal postavit Karel IV. v Praze?',ARRAY['Čechův most','Hlávkův most','Karlův most','Palackého most']::TEXT[],2,'Karlův most.',2,ARRAY[]::TEXT[],NULL,3,'c_dej-4-karel-iv-praha',NULL,NOW()),
('q_dej-4-karel-iv-praha_4','Jak se jmenuje čtvrť, kterou Karel IV. založil v Praze v roce 1348?',ARRAY['Nové Město','Josefov','Hradčany','Malá Strana']::TEXT[],0,'Nové Město pražské.',2,ARRAY[]::TEXT[],NULL,4,'c_dej-4-karel-iv-praha',NULL,NOW()),
('q_dej-4-karel-iv-praha_5','Který chrám dostavoval Petr Parléř?',ARRAY['katedrálu sv. Víta','Týnský chrám','Karlovu kapli','kostel sv. Mikuláše']::TEXT[],0,'Svatovítská katedrála.',2,ARRAY[]::TEXT[],NULL,5,'c_dej-4-karel-iv-praha',NULL,NOW()),
